  window.generateGenshinBannerSvg = function(activeNum, progressNum) {
    const num = Math.max(1, Math.min(5, parseInt(activeNum, 10) || 1));
    const parsedProg = parseInt(progressNum, 10);
    const prog = Math.max(0, Math.min(12, Number.isNaN(parsedProg) ? 0 : parsedProg));

    const bDim = BAB_DIMS[num] || BAB_DIMS[1];
    const babTag = '<g id="bannerBabTitleSlot" class="banner-title-pop">' +
      '<image href="assets/u9/Bab%20' + num + '.svg" xlink:href="assets/u9/Bab%20' + num + '.svg" x="' + bDim.x + '" y="1684" width="' + bDim.w + '" height="' + bDim.h + '" />' +
      '</g>';

    const pDim = PROG_DIMS[prog] || PROG_DIMS[6];
    const counterTag = '<g id="bannerCounterSlot" class="banner-counter-pulse">' +
      '<image href="assets/u9/' + prog + '/12.svg" x="' + pDim.x + '" y="2123.5" width="' + pDim.w + '" height="2753" />' +
      '</g>';

    let svg = BASE_TEMPLATE
      .replace('<!-- SLOT_BAB_TITLE -->', babTag)
      .replace('<!-- SLOT_COUNTER -->', counterTag);

    // Update active tab styling
    for (let i = 0; i < TAB_COORDS.length; i++) {
      const t = TAB_COORDS[i];
      const isActive = t.num === num;
      const oldRegex = new RegExp('<rect\\s+x="' + t.x + '"\\s+y="11887\\.5"\\s+width="271[12]"\\s+height="1348"\\s+rx="422\\.5"\\s+fill="[^"]+"\\s+fill-opacity="[^"]+"\\s+stroke-width="[^"]+"\\s+stroke="[^"]+"\\/>');
      const newRect = '<rect id="tabRect' + t.num + '" x="' + t.x + '" y="11887.5" width="' + t.w + '" height="1348" rx="422.5" fill="' + (isActive ? '#FFFFFF' : 'white') + '" fill-opacity="' + (isActive ? '1' : '0.44') + '" stroke-width="' + (isActive ? '85' : '55') + '" stroke="' + (isActive ? '#3D291F' : 'black') + '"/>';
      svg = svg.replace(oldRegex, newRect);
    }

    return svg;
  };
